using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Diagnostics;using System.Threading.Tasks;
namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 sealed class Compiler {
  public string Root,Work;public Action<string> Log;public List<string> Executables=new List<string>();
  public Compiler(string root,string work,Action<string> log){Root=root;Work=work;Log=log;}
  public string Run(string tool,IEnumerable<string> args,bool allowError=false){string exe=Path.Combine(Root,"bin/arm-none-eabi-"+tool+".exe");var start=new ProcessStartInfo(exe,string.Join(" ",args.Select(U.Quote))){WorkingDirectory=Work,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};start.EnvironmentVariables["PATH"]=Path.Combine(Root,"bin")+";"+Environment.SystemDirectory+";"+Environment.GetEnvironmentVariable("SystemRoot");foreach(var key in new[]{"CPATH","C_INCLUDE_PATH","CPLUS_INCLUDE_PATH","LIBRARY_PATH","COMPILER_PATH","GCC_EXEC_PREFIX"})start.EnvironmentVariables.Remove(key);Executables.Add(exe);using(var p=Process.Start(start)){var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();p.WaitForExit();Task.WaitAll(stdout,stderr);string text=stdout.Result+stderr.Result;if(text.Trim()!="")Log(text.TrimEnd());if(p.ExitCode!=0&&!allowError)throw new Exception(tool+" failed ("+p.ExitCode+"): "+text);return text;}}
  public void Validate(List<string> flags){string profile=Path.Combine(Root,"compact-profile.json");if(!File.Exists(profile))return;var p=U.Read(profile);var machine=flags.Where(f=>f.StartsWith("-m")).ToList();string multilib=Run("gcc",machine.Concat(new[]{"-print-multi-directory"})).Trim();var libs=Json.D(p,"multilibs");if(!libs.ContainsKey(multilib))throw new Exception("경량 GCC에 없는 MCU/ABI: "+multilib);foreach(var pair in Json.D(libs,multilib)){string actual=Run("gcc",machine.Concat(new[]{"-print-file-name=lib"+pair.Key+".a"})).Trim();if(!File.Exists(actual)||Path.GetFullPath(actual)!=Path.GetFullPath(Path.Combine(Root,Convert.ToString(pair.Value))))throw new Exception("Compiler library missing: "+pair.Key);}}
 }
 static class Build {
  public static string WorkRoot(){string root=Path.GetTempPath();if(root.Any(c=>c>127))root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonDocuments),"KlipperNativeWork");if(root.Any(c=>c>127))throw new Exception("ASCII temporary path is required for GCC");Directory.CreateDirectory(root);return Path.GetFullPath(root);}
  static void Cancel(string cancel){if(cancel!=""&&File.Exists(cancel))throw new OperationCanceledException("빌드를 취소했습니다.");}
  public static string Unsupported(KConfig k,string project){string arch=k.Get("BOARD_DIRECTORY");if(!(project=="katapult"?new[]{"rp2040","stm32","lpc176x"}:new[]{"rp2040","stm32"}).Contains(arch))return "현재 지원하는 네이티브 빌드 MCU 계열이 아닙니다.";string file=Path.Combine(U.Assets,project=="katapult"?"katapult-adapters.json":"adapters.json");var approved=U.Read(file);foreach(string name in new[]{"Makefile","src/"+arch+"/Makefile"}){string text=File.ReadAllText(Path.Combine(k.Source,name)).Split(new[]{"# Flash rules"},StringSplitOptions.None)[0];var lines=Regex.Replace(text,@"\\\r?\n\s*"," ").Split('\n').Where(l=>l.Trim()!=""&&!l.TrimStart().StartsWith("#")&&!l.TrimStart().StartsWith("@echo")&&(l.StartsWith("\t")||!Regex.IsMatch(l,@"^(.+?)\s*(\+=|:=|\?=|=)\s*(.*)$"))).Select(l=>Regex.Replace(l.Trim(),@"\s+"," "));string signature=U.Hash(Encoding.UTF8.GetBytes(string.Join("\n",lines)));if(!approved.ContainsKey(name)||!((object[])approved[name]).Select(Convert.ToString).Contains(signature))return "새로운 빌드 절차 검토가 필요합니다: "+name;}return "";}
  static List<string> SourceNames(Recipes r,string key)=>U.Split(r.Get(key)).Select(n=>Normalize("src/"+n)).Distinct().ToList();
  static string Normalize(string path){var parts=new List<string>();foreach(var p in U.Slash(path).Split('/')){if(p=="."||p=="")continue;if(p==".."){if(parts.Count>0)parts.RemoveAt(parts.Count-1);else return "../"+path;}else parts.Add(p);}return string.Join("/",parts);}
  static void Includes(KConfig k,string source,string output){Directory.CreateDirectory(output);U.CopyTree(Path.Combine(source,"src",k.Get("BOARD_DIRECTORY")),Path.Combine(output,"board"));U.CopyTree(Path.Combine(source,"src/generic"),Path.Combine(output,"board-generic/board"));k.Header(Path.Combine(output,"autoconf.h"));}
  public static void Ensure(Versions store,Obj version,KConfig k,Action<string> log,string cancel=""){
   var tree=store.Tree(version);var r=Recipes.For(k);var sources=SourceNames(r,"src-y");if(store.Project=="katapult"&&k.Get("BUILD_DEPLOYER")=="y")sources.AddRange(SourceNames(r,"deployer-y"));sources=sources.Distinct().ToList();var required=new HashSet<string>(sources);required.Add(Recipes.Linker(r,store.Project));if(store.Project=="katapult"&&k.Get("BUILD_DEPLOYER")=="y")required.Add(Recipes.Linker(r,"deployer"));
   string stage=k.Get("RP2040_HAVE_STAGE2")=="y"?Recipes.Stage(k,r):null;if(stage!=null){required.Add(stage+k.Get("RP2040_STAGE2_FILE"));required.Add(stage+"boot_stage2.ld");}
   foreach(var n in new[]{"src/generic/armcm_boot.h","src/command.h","src/initial_pins.h","src/compiler.h","src/generic/armcm_irq.h","src/deployer.h"})if(tree.ContainsKey(n))required.Add(n);
   store.Fetch(version,required,tree);string work=Path.Combine(WorkRoot(),"klipper-cs-deps-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
   try{string compilerRoot=Path.Combine(U.Assets,Json.S(U.Read(Path.Combine(U.Assets,"manifest.json")),"toolchain_directory"));if(compilerRoot.Any(c=>c>127)){U.CopyTree(compilerRoot,Path.Combine(work,"compiler"));compilerRoot=Path.Combine(work,"compiler");}var compiler=new Compiler(compilerRoot,work,_=>{});var flags=Recipes.Flags(k,r,"out").Where(f=>f!="-MD"&&f!="-MMD").ToList();
    for(int pass=0;pass<30;pass++){Cancel(cancel);var quoted=new HashSet<string>();foreach(string name in required.Where(n=>n.StartsWith("src/")).ToList()){string file=Path.Combine(k.Source,name);if(!File.Exists(file))continue;foreach(Match m in Regex.Matches(File.ReadAllText(file),"^\\s*#\\s*include\\s*\"([^\"]+)\"",RegexOptions.Multiline)){string inc=m.Groups[1].Value;foreach(var candidate in new[]{Normalize(U.Slash(Path.GetDirectoryName(name))+"/"+inc),"src/"+inc,"src/"+k.Get("BOARD_DIRECTORY")+"/"+inc.Replace("board/",""),"src/generic/"+inc.Replace("board/","")})if(tree.ContainsKey(candidate)){quoted.Add(candidate);break;}}}if(quoted.Except(required).Any()){store.Fetch(version,quoted.Except(required).ToArray(),tree);required.UnionWith(quoted);}
     U.CopyTree(k.Source,work);Includes(k,work,Path.Combine(work,"out"));File.WriteAllText(Path.Combine(work,"out/probe.c"),"#include \"board/irq.h\"\n#include \"board/pgm.h\"\n#include \"compiler.h\"\n#include \"initial_pins.h\"\n"+(store.Project=="klipper"?"#include \"command.h\"\n":k.Get("BUILD_DEPLOYER")=="y"?"#include \"deployer.h\"\n":""));
     string text=compiler.Run("gcc",flags.Concat(new[]{"-M","-MG","-MT","dependencies"}).Concat(sources).Concat(new[]{"out/probe.c"}),true);if(stage!=null)text+="\n"+compiler.Run("gcc",flags.Concat(new[]{"-I"+stage,"-I"+stage+"asminclude","-DPICO_FLASH_SPI_CLKDIV="+k.Get("RP2040_STAGE2_CLKDIV"),"-M","-MG","-MT","dependencies",stage+k.Get("RP2040_STAGE2_FILE")}),true);
     var incs=new List<string>{"src"};for(int i=0;i<flags.Count;i++){if(flags[i]=="-I"||flags[i]=="-iquote")incs.Add(flags[++i]);else if(flags[i].StartsWith("-I"))incs.Add(flags[i].Substring(2));}incs.AddRange(required.Select(n=>U.Slash(Path.GetDirectoryName(n))));if(stage!=null){incs.Add(stage);incs.Add(stage+"asminclude");}
     Func<string,string> canon=n=>n.StartsWith("out/board-generic/board/")?"src/generic/"+n.Substring(24):n.StartsWith("out/board/")?"src/"+k.Get("BOARD_DIRECTORY")+"/"+n.Substring(10):n;
     var wanted=new HashSet<string>();foreach(string dep in Regex.Split(text.Replace("\\\r\n"," ").Replace("\\\n"," "),@"\s+")){if(dep.Contains(":")||dep=="")continue;foreach(string candidate in new[]{canon(dep)}.Concat(incs.Select(dir=>canon(Normalize(dir+"/"+dep))))){if(tree.ContainsKey(candidate)){wanted.Add(candidate);break;}}}
     var more=wanted.Except(required).ToArray();if(more.Length==0){if(text.Contains("fatal error:")||text.Contains("error:"))throw new Exception("Header discovery failed: "+text);return;}log("필요 헤더 추가: "+more.Length);store.Fetch(version,more,tree);required.UnionWith(more);
    }throw new Exception("Header dependency discovery did not converge");
   }finally{if(Path.GetFullPath(work).StartsWith(WorkRoot(),StringComparison.OrdinalIgnoreCase))Directory.Delete(work,true);}
  }
  public static Obj Run(Versions store,Obj version,KConfig k,string destination,string cancel,Action<string> log){if(Unsupported(k,store.Project)!="")throw new Exception(Unsupported(k,store.Project));Cancel(cancel);Ensure(store,version,k,log,cancel);if(Directory.Exists(destination)&&Directory.EnumerateFileSystemEntries(destination).Any())throw new Exception("Output directory is not empty");Directory.CreateDirectory(destination);string work=Path.Combine(WorkRoot(),"klipper-cs-build-"+Guid.NewGuid().ToString("N")),source=Path.Combine(work,"source"),output=Path.Combine(work,"out");Directory.CreateDirectory(work);var transcript=new List<string>();Action<string> say=s=>{transcript.Add(s);log(s);};File.WriteAllText(Path.Combine(destination,"BUILD_INCOMPLETE"),"building");
   try{U.CopyTree(k.Source,source);Directory.CreateDirectory(output);k.Save(Path.Combine(output,".config"));k.Save(Path.Combine(output,"defconfig"));Includes(k,source,output);var r=Recipes.For(k);var flags=Recipes.Flags(k,r,U.Slash(output));string toolchain=Path.Combine(U.Assets,Json.S(U.Read(Path.Combine(U.Assets,"manifest.json")),"toolchain_directory"));if(toolchain.Any(c=>c>127)){U.CopyTree(toolchain,Path.Combine(work,"compiler"));toolchain=Path.Combine(work,"compiler");}var cc=new Compiler(toolchain,source,say);cc.Validate(flags);string gcc=cc.Run("gcc",new[]{"--version"}).Split('\n')[0],ld=cc.Run("ld",new[]{"--version"}).Split('\n')[0];
    var groups=new Dictionary<string,List<string>>{{store.Project,SourceNames(r,"src-y")}};if(store.Project=="katapult"&&k.Get("BUILD_DEPLOYER")=="y")groups["deployer"]=SourceNames(r,"deployer-y");var objects=new Dictionary<string,string>();var requests=new Dictionary<string,string>();
    var compileNames=groups.Values.SelectMany(n=>n).Distinct().ToArray();int completed=0,total=compileNames.Length+groups.Count*2+(k.Get("RP2040_HAVE_STAGE2")=="y"?1:0)+(groups.ContainsKey("deployer")?1:0)+1;Action progressed=()=>say("@@BUILD_PROGRESS@@"+(++completed)+"/"+total);say("@@BUILD_PROGRESS@@0/"+total);
    foreach(var name in compileNames){Cancel(cancel);string obj=Path.Combine(output,Path.ChangeExtension(name,".o"));Directory.CreateDirectory(Path.GetDirectoryName(obj));say("Compiling "+name);cc.Run("gcc",flags.Concat(new[]{"-c",name,"-o",U.Slash(obj)}));string ctr=obj+".ctr";cc.Run("objcopy",new[]{"-j",".compile_time_request","-O","binary",obj,ctr});objects[name]=obj;requests[name]=Encoding.UTF8.GetString(File.ReadAllBytes(ctr));progressed();}
    var targets=new Dictionary<string,List<string>>();foreach(var group in groups){var gen=new Generators();string request=string.Join("\n",group.Value.Select(n=>requests[n]));gen.Parse(request);string generated=Path.Combine(output,group.Key+"_ctr.c");File.WriteAllText(generated,gen.Generate(k,store.Project,output,"gcc: "+gcc+" binutils: "+ld),new UTF8Encoding(false));string obj=Path.ChangeExtension(generated,".o");cc.Run("gcc",flags.Concat(new[]{"-c",U.Slash(generated),"-o",U.Slash(obj)}));targets[group.Key]=group.Value.Select(n=>objects[n]).Concat(new[]{obj}).ToList();progressed();}
    if(k.Get("RP2040_HAVE_STAGE2")=="y"){string stage=Recipes.Stage(k,r),raw=Path.Combine(output,"stage2raw1.o");cc.Run("gcc",flags.Concat(new[]{"-I"+stage,"-I"+stage+"asminclude","-DPICO_FLASH_SPI_CLKDIV="+k.Get("RP2040_STAGE2_CLKDIV"),"-c",stage+k.Get("RP2040_STAGE2_FILE"),"-o",raw}));cc.Run("ld",new[]{raw,"--script="+stage+"boot_stage2.ld","-o",Path.Combine(output,"stage2raw.o")});cc.Run("objcopy",new[]{"-O","binary",Path.Combine(output,"stage2raw.o"),Path.Combine(output,"stage2raw.bin")});Generators.Stage2(File.ReadAllBytes(Path.Combine(output,"stage2raw.bin")),Path.Combine(output,"stage2.S"));cc.Run("gcc",flags.Concat(new[]{"-c",Path.Combine(output,"stage2.S"),"-o",Path.Combine(output,"stage2.o")}));targets[store.Project].Add(Path.Combine(output,"stage2.o"));progressed();}
    Action<string> link=target=>{Cancel(cancel);string script=Recipes.Linker(r,target),lds=Path.Combine(output,script.Substring(0,script.Length-6)+".ld");Directory.CreateDirectory(Path.GetDirectoryName(lds));cc.Run("gcc",new[]{"-E","-x","assembler-with-cpp","-I",U.Slash(output),"-P",script,"-o",U.Slash(lds)});var args=targets[target].Select(U.Slash).Concat(flags).Concat(new[]{"-Wl,--gc-sections"}).Concat(Recipes.Link(r,target,U.Slash(output))).Concat(new[]{"-o",U.Slash(Path.Combine(output,target+".elf"))});string rsp=Path.Combine(output,target+".rsp");File.WriteAllText(rsp,string.Join("\n",args.Select(a=>"\""+a.Replace("\\","\\\\").Replace("\"","\\\"")+"\"")),new UTF8Encoding(false));say("Linking "+target);cc.Run("gcc",new[]{"@"+U.Slash(rsp)});progressed();};
    link(store.Project);string elf=Path.Combine(output,store.Project+".elf"),bin=Path.Combine(output,store.Project+".bin");cc.Run("objcopy",new[]{"-O","binary",elf,bin});uint start=(uint)U.Number(store.Project=="katapult"?k.Get("FLASH_START"):k.Get("RP2040_HAVE_STAGE2")=="y"?"0x10000000":k.Get("FLASH_APPLICATION_ADDRESS"));var check=Elf.Verify(elf,bin,start);uint family=k.Get("MCU")=="rp2040"?0xe48bff56u:0xe48bff59u;
    if(store.Project=="katapult"){File.WriteAllBytes(bin,Generators.KatapultBinary(File.ReadAllBytes(bin),k,Path.Combine(output,"katapult_payload.c")));File.Copy(bin,Path.Combine(output,"canboot.bin"));if(targets.ContainsKey("deployer")){string obj=Path.Combine(output,"katapult_payload.o");cc.Run("gcc",flags.Concat(new[]{"-c",Path.Combine(output,"katapult_payload.c"),"-o",obj}));targets["deployer"].Add(obj);progressed();link("deployer");cc.Run("objcopy",new[]{"-O","binary",Path.Combine(output,"deployer.elf"),Path.Combine(output,"deployer.bin")});Elf.Verify(Path.Combine(output,"deployer.elf"),Path.Combine(output,"deployer.bin"),(uint)U.Number(k.Get("FLASH_APPLICATION_ADDRESS")));}}
    if(k.Get("BOARD_DIRECTORY")=="rp2040"&&(store.Project=="katapult"||k.Get("RP2040_HAVE_STAGE2")=="y")){string uf2=Path.Combine(output,store.Project+".uf2");Elf.Uf2(elf,uf2,family);if(store.Project=="katapult"){File.Copy(uf2,Path.Combine(output,"canboot.uf2"));byte[] raw=File.ReadAllBytes(uf2);byte[] cleared=raw.Concat(Elf.Block((uint)U.Number(k.Get("LAUNCH_APP_ADDRESS")),new byte[256],0,1,family)).ToArray(); for(int n=0;n<cleared.Length/512;n++){U.Put32(cleared,n*512+20,(uint)n);U.Put32(cleared,n*512+24,(uint)(cleared.Length/512));} File.WriteAllBytes(Path.Combine(output,"katapult.withclear.uf2"),cleared);}}
    var report=new Obj{{"status","success"},{"engine","C# / .NET Framework 4.8"},{"project",store.Project},{"source_version",k.Version},{"source",k.Source},{"elf_check",check},{"python_used",false},{"process_executables",cc.Executables.Distinct().ToArray()},{"artifacts",Directory.GetFiles(output).Where(f=>new[]{".bin",".elf",".uf2",".dict"}.Contains(Path.GetExtension(f))).ToDictionary(f=>Path.GetFileName(f),f=>(object)new Obj{{"size",new FileInfo(f).Length},{"sha256",U.Hash(File.ReadAllBytes(f))}})}};foreach(var pair in k.Summary(store.Project))report[pair.Key]=pair.Value;U.Write(Path.Combine(output,"build-report.json"),report);progressed();say("BUILD SUCCESS: "+Path.Combine(destination,store.Project+".bin"));File.Delete(Path.Combine(destination,"BUILD_INCOMPLETE"));return new Obj{{"output",destination},{"binary",Path.Combine(destination,store.Project+".bin")},{"report",report}};
   }finally{if(Directory.Exists(output)){File.WriteAllText(Path.Combine(output,"build.log"),string.Join("\n",transcript),Encoding.UTF8);U.CopyTree(output,destination);}if(Path.GetFullPath(work).StartsWith(WorkRoot(),StringComparison.OrdinalIgnoreCase))Directory.Delete(work,true);}
  }
 }
